#.originalDocument = GetOriginalDocument();
#.originalDocument = Trim(#.originalDocument);
#.CSTAT = GetXPathValue(#.originalDocument, '/infProt/cStat', 'true');


if(#.CSTAT == '100' || #.CSTAT == '150')
begin
	#.valueCrypt = GetConfigParametersValue('CONNECTIONSTRINGFORMS', '');
	#.connectionString = DecryptData(#.valueCrypt, 'abcdefgh12345678');
	#.acessKey = GetXPathValue(#.originalDocument, '/infProt/chNFe', 'true');
	#.cnpjEmit = Substring(#.acessKey, '6', '14');
	#.serie = Substring(#.acessKey, '22', '3');
	#.documentNumber = Substring(#.acessKey, '25', '9');
	#.selectNFe = 'SELECT PROCESSDATA.DOCUMENTLEGACY FROM TBLOGDOCUMENT LOGDOC INNER JOIN TBLOGDOCUMENTSTATUS LS ON LOGDOC.LOGDOCID EQUAL LS.LOGDOCID INNER JOIN TBPROCESS PROCESS ON LOGDOC.LOGDOCID EQUAL PROCESS.LOGDOCID INNER JOIN TBPROCESSDATA PROCESSDATA ON PROCESS.PROCESSDATAID EQUAL PROCESSDATA.PROCESSDATAID WHERE LOGDOC.DOCUMENTNUMBER = {0} AND LOGDOC.SERIE = {1} AND LOGDOC.CNPJBASE = MOD(TRUNC(QUOTE{2}QUOTE / 10000000000000), 10) * 271818611107 + MOD(TRUNC(QUOTE{2}QUOTE / 1000000000000), 10) * 6321363049 + MOD(TRUNC(QUOTE{2}QUOTE / 100000000000), 10) * 147008443 + MOD(TRUNC(QUOTE{2}QUOTE / 10000000000), 10) * 3418801 + MOD(TRUNC(QUOTE{2}QUOTE / 1000000000), 10) * 79507 + MOD(TRUNC(QUOTE{2}QUOTE / 100000000), 10) * 1849 + MOD(TRUNC(QUOTE{2}QUOTE / 10000000), 10) * 43 + MOD(TRUNC(QUOTE{2}QUOTE / 1000000), 10) AND LOGDOC.CNPJORDEM = ( ( ( MOD(TRUNC(QUOTE{2}QUOTE / 100000), 10) * 43 + MOD(TRUNC(QUOTE{2}QUOTE / 10000), 10) ) * 43 + MOD(TRUNC(QUOTE{2}QUOTE / 1000), 10) ) * 43 + MOD(TRUNC(QUOTE{2}QUOTE / 100), 10) ) AND LOGDOC.CNPJDV = MOD(TRUNC(QUOTE{2}QUOTE / 10), 10) * 10 + MOD(QUOTE{2}QUOTE, 10) AND PROCESS.KIND = 2 AND LS.CSTAT = 100 AND PROCESSDATA.RETXML IS NOT NULL';
	#.commandExtractorNFe = StringFormat(#.selectNFe, #.documentNumber, #.serie, #.cnpjEmit);

	#.enviNFe = OracleHelper(#.connectionString, #.commandExtractorNFe);

	if(IsNullOrEmpty(#.enviNFe) == False())
	begin
		#.enviNFe = DecompressNFe(#.enviNFe);

		#.enviNFe = Replace(#.enviNFe, '<?xml version="1.0" encoding="UTF-8"?>', '');
		#.enviNFe = Replace(#.enviNFe, '<?xml version="1.0" encoding="utf-8"?>', '');
		#.enviNFe = Replace(#.enviNFe, '<?xml version="1.0"?>', '');
		#.versionNFe = GetXPathValue(#.enviNFe, '/NFe/infNFe/@versao', 'true');
		#.infCpl = GetXPathValue(#.enviNFe, '/NFe/infNFe/infAdic/infCpl', 'true');
		#.orderRelease = GetXPathValue(#.originalDocument, '/infProt/dadosAdic/ORDER_RELEASE', 'true');
		#.dominio = GetXPathValue(#.originalDocument, '/infProt/dadosAdic/DOMINIO', 'true');
		#.paramReplaceInfProt = '<?xml version="1.0" encoding="UTF-8"?>';
		#.paramReplaceInfProt2 = '<?xml version="1.0" encoding="utf-8"?>';
		#.infProt = Replace(#.originalDocument, #.paramReplaceInfProt, '');
		#.infProt = Replace(#.infProt, #.paramReplaceInfProt2, '');
		#.infProt = Replace(#.infProt, '<?xml version="1.0"?>', '');
		#.infProt = RegexReplaceGetValue(#.infProt, '<tpEmis>[^<]*</tpEmis>', '');
		#.infProtClean = RegexReplaceGetValue(#.infProt, '<dadosAdic>.*?</dadosAdic>', '');
		#.procNFe = '<?xml version="1.0" encoding="UTF-8"?><nfeProc versao="{0}" xmlns="http://www.portalfiscal.inf.br/nfe" xmlns:ds="http://www.w3.org/2000/09/xmldsig#" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">{1}<protNFe versao="{0}">{2}</protNFe></nfeProc>';
		#.procNFe = StringFormat(#.procNFe, #.versionNFe, #.enviNFe, #.infProtClean);
		if(IsNullOrEmpty(#.dominio) == False() && IsNullOrEmpty(#.orderRelease) == False())
		begin
			if(IsNullOrEmpty(#.infCpl) == False())
			begin
				#.dominioOrderRelease = StringFormat(' IDOR|{0}.{1}|IDOR</infCpl>', #.dominio, #.orderRelease);
				#.procNFe = Replace(#.procNFe, '</infCpl>', #.dominioOrderRelease);
			end
			else
			begin
				#.dominioOrderRelease = StringFormat('<infAdic><infCpl>IDOR|{0}.{1}|IDOR</infCpl></infAdic></infNFe>', #.dominio, #.orderRelease);
				#.procNFe = Replace(#.procNFe, '</infNFe>', #.dominioOrderRelease);
			end
		end
		T.L1/C1 = #.procNFe;
	end
end
%endRuleContent;

%beginRuleContent;
#.originalDocument = GetOriginalDocument();
#.CSTAT = GetXPathValue(#.originalDocument, '/infEvento/cStat', 'true');
#.log = LogHelperMapper('Arquivo original:', #.originalDocument);
#.tpEvento = GetXPathValue(#.originalDocument, 'infEvento/tpEvento', 'true');

if(#.CSTAT == '135' || #.CSTAT == '155' && #.tpEvento == '110111')
begin
	//#.connectionString = 'Data Source=(DESCRIPTION=(ADDRESS=(PROTOCOL=TCP)(HOST= NDD-VM-NFSE02.qualidade.nddigital.local)(PORT=1521))(CONNECT_DATA=(SERVICE_NAME=orcl.nddigital.local)));User Id=APP_NFe_MARCUS_4820;Password=1234';
	#.valueCrypt = GetConfigParametersValue('CONNECTIONSTRINGFORMS', '');
	#.connectionString = DecryptData(#.valueCrypt, 'abcdefgh12345678');
	#.accessKey = GetXPathValue(#.originalDocument, '/infEvento/chNFe', 'true');
	#.selectNFe = 'SELECT PROCESSDATA.DOCUMENTLEGACY FROM TBLOGDOCUMENT LOGDOC INNER JOIN TBLOGDOCUMENTSTATUS LS ON LOGDOC.LOGDOCID EQUAL LS.LOGDOCID INNER JOIN TBPROCESS PROCESS ON LOGDOC.LOGDOCID EQUAL PROCESS.LOGDOCID INNER JOIN TBPROCESSDATA PROCESSDATA ON PROCESS.PROCESSDATAID EQUAL PROCESSDATA.PROCESSDATAID ';
	#.whereNFe = 'WHERE LOGDOC.ACCESSKEY EQUAL QUOTE{0}QUOTE AND PROCESS.KIND=206 AND LS.KIND in (1, 91) AND PROCESSDATA.RETXML IS NOT NULL';
	#.commandExtractorNFe = ConcatString(#.selectNFe, #.whereNFe);
	#.commandExtractorNFe = StringFormat(#.commandExtractorNFe, #.accessKey);
	#.log= LogHelperMapper('Query para nfeProcEvento:', #.commandExtractorNFe);
	#.enviNFe = OracleHelper(#.connectionString, #.commandExtractorNFe);
	if(IsNullOrEmpty(#.enviNFe) == False())
	begin
		#.enviNFe = DecompressNFe(#.enviNFe);
		#.versionNFe = GetXPathValue(#.enviNFe, '/evento/@versao', 'true');
		#.paramReplaceInfEvento= '<?xml version="1.0" encoding="UTF-8"?>';
		#.paramReplaceInfEvento2 = '<?xml version="1.0" encoding="utf-8"?>';
		#.infEvento = Replace(#.originalDocument, #.paramReplaceInfEvento, '');
		#.infEvento = Replace(#.infEvento, #.paramReplaceInfEvento2, '');
		//#.infEvento = RemoveXpathNode(#.infEvento, 'tpEmis', 'false');
		#.procNFeEvento = '<?xml version="1.0" encoding="UTF-8"?><procEventoNFe versao="{0}" xmlns="http://www.portalfiscal.inf.br/nfe" xmlns:ds="http://www.w3.org/2000/09/xmldsig#" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">{1}<retEvento versao="{0}">{2}</retEvento></procEventoNFe>';
		#.procNFe = StringFormat(#.procNFeEvento , #.versionNFe, #.enviNFe, #.infEvento);
	end
	T.L1/C1 = RemoveXpathNode(#.procNFe, 'dadosAdic', 'false');
end
%endRuleContent;

