%beginRuleContent;
#.attribute13 = I.NFE/FISCAL_DOC_HEADER/FSCL_DOC_HDR_ATTRIBUTES/ATTRIBUTE13;

if(IsNullOrEmpty(Trim(#.attribute13)) == False())
begin
	T.NFCom/infNFCom/assinante/nContrato = #.attribute13;
	T.NFCom/infNFCom/assinante/dContratoIni =  ConvertToDateFormat2(I.NFE/FISCAL_DOC_HEADER/FISCAL_DOC_DATE, 'yyyy-MM-dd');

	#.url = GetConfigParametersValue('UrlWebServiceDVenceFat');
	#.user = GetConfigParametersValue('UsuarioWSDVenceFat');
	#.password = GetConfigParametersValue('PasswordWSDVenceFat');

	#.item = I.NFE/FISCAL_DOC_HEADER/TERM_ID;
	#.concatItem = Concat('<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:pub="http://xmlns.oracle.com/oxp/service/PublicReportService"><soapenv:Header/><soapenv:Body><pub:runReport><pub:reportRequest><pub:attributeFormat>xml</pub:attributeFormat><pub:reportAbsolutePath>/Custom/NDD/AR_TERMS.xdo</pub:reportAbsolutePath><pub:parameterNameValues><pub:item><pub:name>P_TERM_ID</pub:name><pub:values><pub:item>', #.item);
	#.concatAposItem = Concat(#.concatItem, '</pub:item></pub:values></pub:item></pub:parameterNameValues></pub:reportRequest><pub:userID>');
	#.concatUser = Concat(#.concatAposItem, #.user);
	#.concatPassword = Concat(#.concatUser, '</pub:userID><pub:password>');
	#.cancatPassLast = Concat(#.concatPassword, #.password);
	#.concatWS = Concat(#.cancatPassLast, '</pub:password></pub:runReport></soapenv:Body></soapenv:Envelope>');

	#.retono = WebRequest(#.url, '200', 'POST','text/xml',#.concatWS);

	#.removeNameSpace = GetXPathNode(#.retono, 'reportBytes', 'true');

	#.retonoTratado = ConvertFromBase64Encoding((#.removeNameSpace), 'UTF-8');
	#.countG_terms = CountNodes(#.retonoTratado, 'G_TERMS');

	#.getDays = GetXPathNode(#.retonoTratado, 'DUE_DAYS', 'true');
	#.getMonth = GetXPathNode(#.retonoTratado, 'DUE_DAY_OF_MONTH', 'true');
	#.getDate = GetXPathNode(#.retonoTratado, 'DUE_DAY_OF_MONTH', 'true');

	#.dhEmiss = I.NFE/FISCAL_DOC_HEADER/FISCAL_DOC_DATE;
	#.dataTratada = Substring(#.dhEmiss, 0, 10);

	if(#.countG_terms <= 1)
	begin
		// dVencFat
		// Verifica se tem DUE_DAYS
		if(IsNullOrEmpty(#.getDays) == False())
		begin
			#.date = Substring(AddDateTimeValue(#.dataTratada, 'yyyy-MM-dd', 3, #.getDays, '2024-02-22'), 0, 10);

			#.dia = PadLeft(SplitValueByPosition(Substring(#.date, 0, 10), '/', 1), 2, '0');
			#.mes = PadLeft(SplitValueByPosition(Substring(#.date, 0, 10), '/', 0), 2, '0');
			#.ano = SplitValueByPosition(Substring(#.date, 0, 10), '/', 2);

			T.NFCom/infNFCom/assinante/dContratoFim = ConvertToDateFormat2((Concat(#.ano, '-', #.mes, '-', #.dia)), 'yyyy-MM-dd');

		end
		else
		begin
			if(IsNullOrEmpty(#.getMonth) == False())
			begin
				#.mesAtual = ConvertToInt32(SplitValueByPosition(#.dataTratada, '-', 1));
				#.anoAtual = ConvertToInt32(SplitValueByPosition(#.dataTratada, '-', 0));

				#.mesNovo = #.mesAtual + 1;
				#.anoNovo = #.anoAtual;

				if(#.mesNovo > 12)
				begin
					#.mesNovo = 1;
					#.anoNovo = #.anoAtual + 1;
				end

				#.mesNovoFormatado = PadLeft(#.mesNovo, 2, '0');
				#.diaFormatado = PadLeft(#.getMonth, 2, '0');

				T.NFCom/infNFCom/assinante/dContratoFim = ConvertToDateFormat2(Concat(#.anoNovo, '-', #.mesNovoFormatado, '-', #.diaFormatado), 'yyyy-MM-dd');

			end
			else
			begin
				if(IsNullOrEmpty(#.getDate) == False())
				begin
					#.dataTratada = Substring(#.getDate, 0, 10);

					#.dia = PadLeft(SplitValueByPosition(#.dataTratada, '-', 2), 2, '0');
					#.mes = PadLeft(SplitValueByPosition(#.dataTratada, '-', 1), 2, '0');
					#.ano = SplitValueByPosition(#.dataTratada, '-', 0);

					T.NFCom/infNFCom/assinante/dContratoFim = ConvertToDateFormat2(Concat(#.ano, '-', #.mes, '-', #.dia), 'yyyy-MM-dd');

				end
			end
		end
	end
end
else
begin
		T.NFCom/infNFCom/assinante/nContrato = '000';
		T.NFCom/infNFCom/assinante/dContratoIni =  ConvertToDateFormat2(I.NFE/FISCAL_DOC_HEADER/FISCAL_DOC_DATE, 'yyyy-MM-dd');
end
%endRuleContent;

%beginRuleContent;
#.chNFe = I.LINHA000/ChaveAcesso;
#.tipoOperacao = ConvertToInt32(I.LINHA000/TipoOperacaoNF);
#.justificativaCancInutilizacao = I.LINHA000/JustificativaCancInutilizacao;
$.chaveMontada = '';
#.connectionString = DecryptData(GetConfigParametersValue('CONNECTION_STRING'), 'abcdefgh12345678');

if(!IsNullOrEmpty(#.tipoOperacao) && #.tipoOperacao != 'xml')
begin
	if(#.tipoOperacao == 2)
	begin
		#.CNPJEmissorNF = I.HEADER/CNPJEmissorNF;

		if(!IsNullOrEmpty(#.CNPJEmissorNF)  && IsNullOrEmpty(#.chNFe))
		begin
			#.cnpjSerie = ConcatString(#.CNPJEmissorNF,PadLeft(I.LINHA000/SerieNF,'0',3,false));
			#.sequencialInicial = I.LINHA000/SequencialnNFIni;
			#.documentKey = ConcatString(#.cnpjSerie,PadLeft(#.sequencialInicial,'0',9,false));
			#.documentKeyAspas = Concat('\'',#.documentKey,'\'');
			#.query = 'SELECT TOP 1 CONVERT(VARCHAR(18),DOCUMENTKEY1) + REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY2) + REPLICATE(\'0\', 8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY3) AS CHAVE FROM TBCONINTEGRATIONRETURN WHERE CNPJCOMPANY = SUBSTRING({0},1,14) AND SERIE = SUBSTRING({0},15,3) AND DOCUMENTNUMBER=SUBSTRING({0},18,9) AND SendType=1 ORDER BY INSERTDATE DESC';
			#.commandSelect = StringFormat(#.query,#.documentKeyAspas);
			#.chaveNFe = MSqlServerHelper(#.connectionString, #.commandSelect);

			if(!IsNullOrEmpty(#.chaveNFe))
			begin
				$.chaveMontada = #.chaveNFe;
				#.chNFeFinal = ConcatString('NFe', #.chaveNFe);
			end
			else
			begin
				if(GetLength(#.chNFe) < 44)
				begin
					#.SequencialnNFIni = Substring(#.sequencialInicial, 1, 8);
					#.PrimeiraParteDachNFe = ConcatString(Substring(#.chNFe, 0, 6),#.CNPJEmissorNF);
					#.ParteDomeioDeUmachNFe = Substring(#.chNFe, 20, 14);
					#.chNFeFormada = ConcatString(ConcatString(#.PrimeiraParteDachNFe,ConcatString(#.ParteDomeioDeUmachNFe, '1')),#.SequencialnNFIni);
					#.digitoVerificador = CalculateVerifierDigit(#.chNFeFormada);
					$.chaveMontada = ConcatString(#.chNFeFormada, #.digitoVerificador);
					#.chNFeFinal = ConcatString('NFe', $.chaveMontada);
				end
			end
		end
		else
		begin
			#.chNFeFinal = #.chNFe;
			$.chaveMontada = #.chNFeFinal;
		end

		T.nfeCancInut/chNFe =$.chaveMontada;
	end
	else
	begin
		if(!IsNullOrEmpty(#.chNFe))
		begin
			$.chaveMontada = #.chNFe;
			#.chNFeFinal = ConcatString('NFe', #.chNFe);
			T.nfeCancInut/chNFe = #.chNFeFinal;
		end
	end
end
else
begin
	#.queryContigencia = 'SELECT ISNULL((SELECT TOP 1 REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY1))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY1)+REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY2)+REPLICATE(\'0\',  8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY3)FROM TBLOGDOCUMENT (NOLOCK) WHERE DOCUMENTNUMBERCUT = SUBSTRING({0} , 7,28) AND HIDDEN=0 ORDER BY LOGDOCID DESC),{0}) as \'KEY\'  ';
	#.commandSelectContigencia = StringFormat(#.queryContigencia, #.documentKey);
	#.keySelect = MSqlServerHelper(#.connectionString, #.commandSelectContigencia);
	T.nfeCancInut/chNFe = #.keySelect;
end
%endRuleContent;

%beginRuleContent;
#.chNFe = I.LINHA000/ChaveAcesso;
#.tipoOperacao = ConvertToInt32(I.LINHA000/TipoOperacaoNF);
#.justificativaCancInutilizacao = I.LINHA000/JustificativaCancInutilizacao;
$.chaveMontada = '';
#.connectionString = DecryptData(GetConfigParametersValue('CONNECTION_STRING'), 'abcdefgh12345678');

if(!IsNullOrEmpty(#.tipoOperacao) && #.tipoOperacao != 'xml')
begin
	if(#.tipoOperacao == 2)
	begin
		#.CNPJEmissorNF = I.HEADER/CNPJEmissorNF;

		if(!IsNullOrEmpty(#.CNPJEmissorNF)  && IsNullOrEmpty(#.chNFe))
		begin
			#.cnpjSerie = ConcatString(#.CNPJEmissorNF,PadLeft(I.LINHA000/SerieNF,'0',3,false));
			#.sequencialInicial = I.LINHA000/SequencialnNFIni;
			#.documentKey = ConcatString(#.cnpjSerie,PadLeft(#.sequencialInicial,'0',9,false));
			#.documentKeyAspas = Concat('\'',#.documentKey,'\'');
			#.query = 'SELECT TOP 1 CONVERT(VARCHAR(18),DOCUMENTKEY1) + REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY2) + REPLICATE(\'0\', 8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY3) AS CHAVE FROM TBCONINTEGRATIONRETURN WHERE CNPJCOMPANY = SUBSTRING({0},1,14) AND SERIE = SUBSTRING({0},15,3) AND DOCUMENTNUMBER=SUBSTRING({0},18,9) AND SendType=1 ORDER BY INSERTDATE DESC';
			#.commandSelect = StringFormat(#.query,#.documentKeyAspas);
			#.chaveNFe = MSqlServerHelper(#.connectionString, #.commandSelect);

			if(!IsNullOrEmpty(#.chaveNFe))
			begin
				$.chaveMontada = #.chaveNFe;
				#.chNFeFinal = ConcatString('NFe', #.chaveNFe);
			end
			else
			begin
				if(GetLength(#.chNFe) < 44)
				begin
					#.SequencialnNFIni = Substring(#.sequencialInicial, 1, 8);
					#.PrimeiraParteDachNFe = ConcatString(Substring(#.chNFe, 0, 6),#.CNPJEmissorNF);
					#.ParteDomeioDeUmachNFe = Substring(#.chNFe, 20, 14);
					#.chNFeFormada = ConcatString(ConcatString(#.PrimeiraParteDachNFe,ConcatString(#.ParteDomeioDeUmachNFe, '1')),#.SequencialnNFIni);
					#.digitoVerificador = CalculateVerifierDigit(#.chNFeFormada);
					$.chaveMontada = ConcatString(#.chNFeFormada, #.digitoVerificador);
					#.chNFeFinal = ConcatString('NFe', $.chaveMontada);
				end
			end
		end
		else
		begin
			#.chNFeFinal = #.chNFe;
			$.chaveMontada = #.chNFeFinal;
		end

		T.nfeCancInut/chNFe =$.chaveMontada;
	end
	else
	begin
		if(!IsNullOrEmpty(#.chNFe))
		begin
			$.chaveMontada = #.chNFe;
			#.chNFeFinal = ConcatString('NFe', #.chNFe);
			T.nfeCancInut/chNFe = #.chNFeFinal;
		end
	end
end
else
begin
	#.queryContigencia = 'SELECT ISNULL((SELECT TOP 1 REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY1))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY1)+REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY2)+REPLICATE(\'0\',  8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY3)FROM TBLOGDOCUMENT (NOLOCK) WHERE DOCUMENTNUMBERCUT = SUBSTRING({0} , 7,28) AND HIDDEN=0 ORDER BY LOGDOCID DESC),{0}) as \'KEY\'  ';
	#.commandSelectContigencia = StringFormat(#.queryContigencia, #.documentKey);
	#.keySelect = MSqlServerHelper(#.connectionString, #.commandSelectContigencia);
	T.nfeCancInut/chNFe = #.keySelect;
end
%endRuleContent;

