%beginRuleContent;
#.cStat = I.infEvento/cStat;
#.TypeEVT = I.infEvento/tpEvento;
#.DescricaoStatusAutorizacao = I.infEvento/xMotivo;

if(IsNullOrEmpty(#.cStat) != True())
begin
	if(#.cStat == '100')
	begin
		#.DescricaoStatusAutorizacao = 'Autorizado';
	end
	if(#.cStat == '110')
	begin
		#.DescricaoStatusAutorizacao = 'Denegado ';
	end
	if(#.cStat == '101' || #.cStat == '155')
	begin
		#.DescricaoStatusAutorizacao = 'NF-e Cancelada ';
	end
	if(#.cStat == '102')
	begin
		#.DescricaoStatusAutorizacao = 'NF-e Inutilizada ';
	end
	if(#.cStat == '027')
	begin
		#.DescricaoStatusAutorizacao = 'Erro Expirou a Data do Certificado Digital';
	end
	if(#.cStat == '010')
	begin
		#.DescricaoStatusAutorizacao = 'Erro tecnico na Assinatura do XML';
	end
	if(Contains(#.cStat, 135) && Contains(#.TypeEVT, 110111))
	begin
		#.DescricaoStatusAutorizacao = 'NF-e Cancelada';
	end
	if(#.cStat == '135' && #.TypeEVT != '110111')
	begin
		#.DescricaoStatusAutorizacao = 'Evento registrado e vinculado a NF-e';
	end
	if(#.cStat == '35' && #.TypeEVT == '110111')
	begin
		#.DescricaoStatusAutorizacao = 'Erro Cancelamento da NF-e';
	end
	if(#.cStat < '200' && #.cStat > '900' && #.cStat != '801')
	begin
		#.DescricaoStatusAutorizacao = 'Rejeitado';
	end
	if(#.cStat == '900')
	begin
		#.DescricaoStatusAutorizacao = 'Convertido satisfatoriamente';
	end
	if(#.cStat == '801')
	begin
		#.DescricaoStatusAutorizacao = 'Erro de conversao';
	end
	if(IsNullOrEmpty(#.DescricaoStatusAutorizacao) != True())
	begin
		T.LINHA_RETURN/DescricaoStatusAutorizacao = Replace(#.DescricaoStatusAutorizacao, '.', '');
	end
	else
	begin
		T.LINHA_RETURN/DescricaoStatusAutorizacao = '                                                  ';
	end
end
else
begin
	T.LINHA_RETURN/DescricaoStatusAutorizacao = 'Nao Encontrado Cstat Valido';
end

%endRuleContent;

