%beginRuleContent;
#.bloco290 = I.infProt/bloco290;
#.nProt = I.infProt/nProt;
#.chave = I.infProt/chNFe;
#.chNFe = Concat('\'',#.chave,'\'');

if(IsNullOrEmpty(#.bloco290) != True() && #.bloco290 != 'xml')
begin
	#.bloco290Final = #.bloco290;
end
else
begin	
	if(!IsNullOrEmpty(#.chNFe) && #.chNFe != 'xml')
	begin
		#.ConnectionString  = DecryptData(GetConfigParametersValue('CONNECTION_STRING'), 'abcdefgh12345678');
		#.Query = 'SELECT TOP 1 Bloco290 FROM tbConIntegrationReturn WHERE ((DocumentKey1 = SUBSTRING( {0} , 1 , 18) AND DocumentKey2 = SUBSTRING( {0} , 19 , 18) AND DocumentKey3 = SUBSTRING( {0} , 37 , 8)) OR (CNPJCompany = SUBSTRING({0},7,14) AND DocumentNumber = SUBSTRING({0},26,9) AND Serie = SUBSTRING({0},23,3))) AND SendType = 1 AND Bloco290 IS NOT NULL ORDER BY insertdate DESC';
		#.CommandSelect = StringFormat(#.Query,#.chNFe);
		#.bloco290 = MSqlServerHelper(#.ConnectionString,#.CommandSelect);

		if(!IsNullOrEmpty(#.bloco290))
		begin
			#.bloco290Final = #.bloco290;
		end
		else
		begin
			#.bloco290Final = '';
		end
	end
end

if(!IsNullOrEmpty(#.nProt) && #.nProt != 'xml' && ConvertToInt32(#.nProt) != 0)
begin
	#.nProtFinal = #.nProt;
end
else
begin
	#.nProtFinal = '               ';
end

if(!IsNullOrEmpty(#.bloco290Final) && #.bloco290Final != 'xml')
begin
	#.primeiraParteBloco290 = Substring(#.bloco290Final,0,21);
	#.segundaParteBloco290 = Substring(#.bloco290Final,80,ConvertToInt32(Sum(GetLength(#.bloco290Final),-80),316));
	T.LINHA_RETURN/Bloco_290 = Concat(Concat(Concat(#.primeiraParteBloco290,#.chave),#.nProtFinal),#.segundaParteBloco290);
end
else
begin
	T.LINHA_RETURN/Bloco_290 = '                                                                                                                                                                                                                                                                                                                                                           ';
end
%endRuleContent;

