if(!IsNullOrEmpty(#.tipoOperacao) && #.tipoOperacao != 'xml')
begin
	if(#.tipoOperacao == 2)
	begin
		#.CNPJEmissorNF = I.HEADER/CNPJEmissorNF;
		if(!IsNullOrEmpty(#.CNPJEmissorNF))
		begin
			#.cnpjSerie = ConcatString(#.CNPJEmissorNF,PadLeft(I.LINHA000/SerieNF,'0',3,false));
			#.sequencialInicial = I.LINHA000/SequencialnNFIni;
			#.documentKey = ConcatString(#.cnpjSerie,PadLeft(#.sequencialInicial,'0',9,false));
			#.documentKeyAspas = Concat('\'',#.documentKey,'\'');
			#.query = 'SELECT TOP 1 CONVERT(VARCHAR(18),DOCUMENTKEY1) + REPLICATE({0}, 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY2) + REPLICATE({0}, 8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY3) AS CHAVE FROM TBCONINTEGRATIONRETURN WHERE CNPJCOMPANY = SUBSTRING({0},1,14) AND SERIE = SUBSTRING({0},15,3) AND DOCUMENTNUMBER=SUBSTRING({0},18,9) AND SendType=1 ORDER BY INSERTDATE DESC';
			#.commandSelect = StringFormat(#.query,#.documentKeyAspas);
			#.chaveNFe = MSqlServerHelper(#.connectionString, #.commandSelect);
			if(!IsNullOrEmpty(#.chaveNFe))
			begin
				$.chaveMontada = #.chaveNFe;
				#.chNFeFinal = ConcatString('NFe', #.chaveNFe);
			end
			else
			begin
				if(GetLength(#.chNFe) < 44)
				begin
					#.SequencialnNFIni = Substring(#.sequencialInicial, 1, 8);
					#.PrimeiraParteDachNFe = ConcatString(Substring(#.chNFe, 0, 6),#.CNPJEmissorNF);
					#.ParteDomeioDeUmachNFe = Substring(#.chNFe, 20, 14);
					#.chNFeFormada = ConcatString(ConcatString(#.PrimeiraParteDachNFe,ConcatString(#.ParteDomeioDeUmachNFe, '1')),#.SequencialnNFIni);
					#.digitoVerificador = CalculateVerifierDigit(#.chNFeFormada);
					$.chaveMontada = ConcatString(#.chNFeFormada, #.digitoVerificador);
					#.chNFeFinal = ConcatString('NFe', $.chaveMontada);
				end
			end
			T.nfeCancInut/chNFe = #.chNFeFinal;
		end
	end
	else
	begin
		if(!IsNullOrEmpty(#.chNFe))
		begin
			$.chaveMontada = #.chNFe;
			#.chNFeFinal = ConcatString('NFe', #.chNFe);
			T.nfeCancInut/chNFe = #.chNFeFinal;
		end
	end
end
else
begin
	#.queryContigencia = 'SELECT ISNULL((SELECT TOP 1 REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY1))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY1)+REPLICATE(\'0\', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY2)+REPLICATE(\'0\',  8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) +  CONVERT(VARCHAR(MAX),DOCUMENTKEY3)FROM TBLOGDOCUMENT (NOLOCK) WHERE DOCUMENTNUMBERCUT = SUBSTRING({0} , 7,28) AND HIDDEN=0 ORDER BY LOGDOCID DESC),{0}) as \'KEY\'  ';
	#.commandSelectContigencia = StringFormat(#.queryContigencia, #.documentKey);
	#.keySelect = MSqlServerHelper(#.connectionString, #.commandSelectContigencia);
	T.nfeCancInut/chNFe = #.keySelect;
end
%endRuleContent;

