T.inutNFe/infInut/mod = #.modelo;
#.serie = ConvertToInt32(#.serie);
#.numeroInicial = ConvertToInt32(#.numeroInicial);
#.numeroFinal = ConvertToInt32(#.numeroFinal);
if(#.serie == null) #.serie = '';
if(#.numeroInicial == null) #.numeroInicial = '';
if(#.numeroFinal == null) #.numeroFinal = '';
T.inutNFe/infInut/serie = #.serie;
T.inutNFe/infInut/nNFIni = #.numeroInicial;
T.inutNFe/infInut/nNFFin = #.numeroFinal;
