#.TN = RegexGetMatchValues(#.originalDocument,'TN[0-9]{10}[-][0-9]{4}', ';');
#.PP = RegexGetMatchValues(#.originalDocument,'POPPBR[0-9]{8}', ';');

if(Contains(#.originalDocument,'<infCte') == 'true')
begin
	#.valorString = '<ObsCont xCampo="xPed"><xTexto>';
	if(IsNullOrEmpty(#.PO) == 'false')
	begin
		#.PO = RegexGetItems(#.PO, ';');
		#.extra = Concat(#.valorString, #.PO, '</xTexto></ObsCont></compl>');
		#.originalDocument = ReplaceValue(#.originalDocument, '</compl>' ,#.extra);
	end
	else
	begin
		if(IsNullOrEmpty(#.CC) == 'false')
		begin
			#.CC = RegexGetItems(#.CC, ';');

			if(IsNullOrEmpty(#.FN) == 'false')
			begin
				#.FN = RegexGetItems(#.FN, ';');
				#.CC = Concat(#.CC,';',#.FN);
			end
			if(IsNullOrEmpty(#.TN) == 'false')
			begin
				#.TN = RegexGetItems(#.TN, ';');
				#.CC =  Concat(#.CC,';',#.TN);
			end
			#.extra = Concat(#.valorString, #.CC,  '</xTexto></ObsCont></compl>');
			#.originalDocument = ReplaceValue(#.originalDocument, '</compl>', #.extra);
		end
	end
end
else
begin
	if(RegexIsMatch(#.originalDocument,'<infNFe') == 'true')
	begin
		if(IsNullOrEmpty(#.PO) == 'false')
		begin
			#.PO = RegexGetItems(#.PO, ';');
			#.extra = Concat('<compra><xPed>', #.PO, '</xPed></compra></infNFe>');
			#.originalDocument = ReplaceValue(#.originalDocument, '</infNFe>' , #.extra);
		end
		else
		begin
			if(IsNullOrEmpty(#.CC) == 'false')
			begin
				#.CC = RegexGetItems(#.CC, ';');

				if(IsNullOrEmpty(#.FN) == 'false')
				begin
					#.FN = RegexGetItems(#.FN, ';');
					#.CC =  Concat(#.CC,';',#.FN);
				end
				if(IsNullOrEmpty(#.TN) == 'false')
				begin
					#.TN = RegexGetItems(#.TN, ';');
					#.CC =  Concat(#.CC,';',#.TN);
				end
				#.extra = Concat('<compra><xPed>',#.CC,'</xPed></compra></infNFe>');
				#.originalDocument = ReplaceValue(#.originalDocument, '</infNFe>' , #.extra);
			end
		end
	end
	else
	begin
		if(Contains(#.originalDocument,'<InfRps') == True())
		begin
			if(IsNullOrEmpty(#.PO) == False() || IsNullOrEmpty(#.PP) == False())
			begin
				if(IsNullOrEmpty(#.PO) == False())
				begin
					#.PO = RegexGetItems(#.PO, ';');
