					begin
						#.PP = RegexGetItems(#.PP, ';');
						#.extra = Concat(';',#.PP,'</DiscriminacaoServico>');
						#.originalDocument = ReplaceValue(#.originalDocument, '</DiscriminacaoServico>' , #.extra);
					end
				end
			end
			else
			begin
				if(IsNullOrEmpty(#.CC) == False())
				begin
					#.CC = RegexGetItems(#.CC, ';');

					if(IsNullOrEmpty(#.FN) == False())
					begin
						#.FN = RegexGetItems(#.FN, ';');
						#.CC =  Concat(#.CC,';',#.FN);
					end
					if(IsNullOrEmpty(#.TN) == False())
