#.QueryDeleteExpiredCnpj = 'DELETE FROM TBCNPJSIMPLETAX WHERE DATEADD(MONTHCOMMA -1COMMA GETDATE()) > INSERTDATE';
#.Log = LogHelperMapper('Log: Query para Deletar registro de Cnpj Vencido', #.QueryDeleteExpiredCnpj);
#.ResultDeleteExpiredCnpj = MSqlServerHelper(#.ConnectionString,#.QueryDeleteExpiredCnpj);

#.JobKey = I.XmlNfse/JobKey;
