%beginRuleContent;
#.ConnectionString = GetConfigParametersValue('CONNECTIONSTRING','');
#.Log = LogHelperMapper('Log: ConnectionString criptografada',#.ConnectionString);
#.ConnectionString = DecryptData(#.ConnectionString,'abcdefgh12345');
#.Log = LogHelperMapper('Log: ConnectionString',#.ConnectionString);

#.QueryDeleteExpiredCnpj = 'DELETE FROM TBCNPJSIMPLETAX WHERE DATEADD(MONTHCOMMA -1COMMA GETDATE()) > INSERTDATE';
#.Log = LogHelperMapper('Log: Query para Deletar registro de Cnpj Vencido', #.QueryDeleteExpiredCnpj);
#.ResultDeleteExpiredCnpj = MSqlServerHelper(#.ConnectionString,#.QueryDeleteExpiredCnpj);

#.JobKey = I.XmlNfse/JobKey;
#.Log = LogHelperMapper('JobKey', #.JobKey);

#.QueryIsConsult = 'SELECT TOP 1 CAST(ConsultaSimplesNacional AS VARCHAR(MAX)) + QUOTE#QUOTE + ChaveConsultaMIDAS FROM tbConfiguracoesSettings WHERE JOBKEY EQUAL QUOTE{0}QUOTE';
#.QueryIsConsult = StringFormat(#.QueryIsConsult, #.JobKey);
#.Log = LogHelperMapper('Log: Query para ver se deve consultar Midas', #.QueryIsConsult);

#.ResultIsConsult = MSqlServerHelper(#.ConnectionString,#.QueryIsConsult);
#.Log = LogHelperMapper('Log: Resultado deve consultar midas', #.ResultIsConsult);

#.ShouldConsultSimpleTax = SplitValueByPosition(#.ResultIsConsult,'#', 0);
#.ConsultKey = SplitValueByPosition(#.ResultIsConsult,'#', 1);

#.CNPJ = I.XmlNfse/DadosPrestador/Cnpj;
#.Log = LogHelperMapper('Log: CNPJ sem PadLeft', #.CNPJ);
#.CNPJ = PadLeft(#.CNPJ, '0', 14) ;
#.Log = LogHelperMapper('Log: CNPJ com PadLeft', #.CNPJ);

#.GetOriginalSimpleTax = 0;

if(#.ShouldConsultSimpleTax == 1)
begin
	#.QueryIsSimpleTax = 'SELECT TOP 1 ISSIMPLETAX FROM TBCNPJSIMPLETAX WHERE CNPJ EQUAL QUOTE{0}QUOTE';
	#.QueryIsSimpleTax = StringFormat(#.QueryIsSimpleTax, #.CNPJ);
	#.Log = LogHelperMapper('Log: Query para ver se CNPJ é Simples Nacional', #.QueryIsSimpleTax);

	#.ResultIsSimpleTax = MSqlServerHelper(#.ConnectionString,#.QueryIsSimpleTax);
	#.Log = LogHelperMapper('Log: Resultado da query CNPJ é Simples Nacional', #.ResultIsSimpleTax);

	if(#.ResultIsSimpleTax == 0)
	begin
		T.Rps/InfRps/OptanteSimplesNacional = 2;
	end
	else
	begin
		if(#.ResultIsSimpleTax == 1)
		begin
			T.Rps/InfRps/OptanteSimplesNacional = 1;
		end
		else
		begin
			#.Log = LogHelperMapper('Log: WS MIDAS', 'Vai efetuar chamada da função que consulta sn na MIDAS' );

			#.UrlMidas = GetConfigParametersValue('URLMIDAS', '');
			#.ReturnXPath = 'DataReturn/Rows/ParseDataRow/Columns/ParseDataColumn[Key = "SituacaoSIMPLES"]/Value';
			#.ParamCnpjFormat = 'CNPJ={0}';
			#.ParamCnpj = StringFormat(#.ParamCnpjFormat, #.CNPJ);

			#.ResultMidas = CallMidasWebService(#.UrlMidas, #.ReturnXPath, #.ConsultKey, 'SimplesNacional', #.ParamCnpj);
			#.Log = LogHelperMapper('Log: Retorno da MIDAS', #.ResultMidas);

			#.QueryInsertCnpjSN = 'IF ((SELECT COUNT(*) FROM TBCNPJSIMPLETAX WHERE CNPJ EQUAL {0}) > 0) UPDATE TBCNPJSIMPLETAX SET ISSIMPLETAX EQUAL 1 WHERE CNPJ EQUAL {0} ELSE INSERT TBCNPJSIMPLETAX (CNPJCOMMA ISSIMPLETAXCOMMA INSERTDATE) VALUES ({0}COMMA {1}COMMA GETDATE())';

			if(StartsWith(#.ResultMidas,'NÃO') == True())
			begin
				#.Log = LogHelperMapper('Log: ResultMidas inicia com NÃO', '');
				#.QueryInsertCnpjSN = StringFormat(#.QueryInsertCnpjSN, #.CNPJ, '0');
				T.Rps/InfRps/OptanteSimplesNacional = 2;
				#.ResultInsertCnpjSN = MSqlServerHelper(#.ConnectionString,#.QueryInsertCnpjSN);
			end
			else
			begin
				if(StartsWith(#.ResultMidas,'Optante') == True())
				begin
					#.Log = LogHelperMapper('Log: ResultMidas inicia com Optante', '');
					#.QueryInsertCnpjSN = StringFormat(#.QueryInsertCnpjSN, #.CNPJ, '1');
					T.Rps/InfRps/OptanteSimplesNacional = 1;
					#.ResultInsertCnpjSN = MSqlServerHelper(#.ConnectionString,#.QueryInsertCnpjSN);
				end
				else
				begin
					#.GetOriginalSimpleTax = 1;
				end
			end
		end
	end
end

if(#.ShouldConsultSimpleTax == 0 || #.GetOriginalSimpleTax == 1 || IsNullOrEmpty(#.ShouldConsultSimpleTax) == True())
begin
	#.Log = LogHelperMapper('Log: Capturando SimplesNacional da Origem', '');
	#.OptanteSimplesNacional = I.XmlNfse/OptanteSimplesNacional;
	if(Contains(#.OptanteSimplesNacional,'S') == True() || Contains(#.OptanteSimplesNacional,'s') == True())
	begin
		T.Rps/InfRps/OptanteSimplesNacional = 1;
	end
	else
	begin
		if(Contains(#.OptanteSimplesNacional,'N') == True() || Contains(#.OptanteSimplesNacional,'n') == True())
		begin
			T.Rps/InfRps/OptanteSimplesNacional = 2;
		end
		else
		begin
			if(IsNullOrEmpty(#.OptanteSimplesNacional) == True())
			begin
				T.Rps/InfRps/OptanteSimplesNacional = 3;
			end
			else
			begin
				T.Rps/InfRps/OptanteSimplesNacional = #.OptanteSimplesNacional;
			end

		end

	end
end
%endRuleContent;

