#.ValorISSRetido = I.NeoGridRPS/RPS/servico/vlISSRet;
#.DescontoIncondicionado = I.NeoGridRPS/RPS/servico/desIncond;
#.DescontoCondicionado = I.NeoGridRPS/RPS/servico/desCond;


if(IsNullOrEmpty(#.ValorLiquidoNfse) == True())
begin
	#.ValorServicos = DecimalFormaterDelimiter(#.ValorServicos, 2, 1);
	#.ValorPIS = DecimalFormaterDelimiter(#.ValorPIS, 2, 1);
	#.ValorCOFINS  = DecimalFormaterDelimiter(#.ValorCOFINS, 2, 1);
	#.ValorINSS  = DecimalFormaterDelimiter(#.ValorINSS, 2, 1);
	#.ValorIR = DecimalFormaterDelimiter(#.ValorIR, 2, 1);
	#.ValorCSLL = DecimalFormaterDelimiter(#.ValorCSLL, 2, 1);
	#.OutrasRetençoes = DecimalFormaterDelimiter(#.OutrasRetençoes, 2, 1);
	#.ValorISSRetido = DecimalFormaterDelimiter(#.ValorISSRetido, 2, 1);
	#.DescontoIncondicionado = DecimalFormaterDelimiter(#.DescontoIncondicionado, 2, 1);
	#.DescontoCondicionado = DecimalFormaterDelimiter(#.DescontoCondicionado, 2, 1);


	#.valueSum1 = Sum(#.ValorPIS, #.ValorCOFINS);
	#.valueSum2 = Sum(#.ValorINSS, #.ValorIR);
	#.valueSum3 = Sum(#.ValorCSLL, #.OutrasRetençoes);
	#.valueSum4 = Sum(#.ValorISSRetido, #.DescontoIncondicionado);

	#.resulSum1 = Sum(#.valueSum1, #.valueSum2);
	#.resulSum2 = Sum(#.valueSum3, #.valueSum4);

	#.resulSum3 = Sum(#.resulSum1, #.resulSum2);

	#.resulSum4 = Sum(#.resulSum3, #.DescontoCondicionado);

	#.ValorLiquidoNfse = Subtract(#.ValorServicos, #.resulSum4);
	#.ValorLiquidoNfse = DecimalFormaterDelimiter(#.ValorLiquidoNfse, 2, 2);

	T.Rps/InfRps/Servicos/Valores/ValorLiquidoNfse = ReplaceDotToComma(#.ValorLiquidoNfse);
end
else
begin
	T.Rps/InfRps/Servicos/Valores/ValorLiquidoNfse = ReplaceDotToComma(#.ValorLiquidoNfse);
end
