%beginRuleContent;
#.CST = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/CST_COFINS;

if(IsNullOrEmpty(#.CST) == False())
begin
	#.vBC = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_BASE_COFINS;
	#.pCOFINS = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_ALIQ_COFINS;
	#.vCOFINS = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_TOTAL_COFINS;
	#.qBCProd = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/QUANT_BC_COFINS;
	#.vAliqProd = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/ALIQ_COFINS;

	#.CST = PadRight(#.CST, '0', 2);
	if(#.CST == '01' || #.CST == '02')
	begin
		T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSAliq = &new&;
		T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSAliq/CST = #.CST;
		T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSAliq/vBC = DecimalFormaterDelimiter(#.vBC, 2, 1);
		T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSAliq/pCOFINS = DecimalFormaterDelimiter(#.pCOFINS, 2, 1);
		T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSAliq/vCOFINS = DecimalFormaterDelimiter(#.vCOFINS, 2, 1);
	end
	else
	begin
		if(#.CST == '03')
		begin
			T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSQtde = &new&;
			T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSQtde/CST = #.CST;
			T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSQtde/qBCProd = DecimalFormaterDelimiter(#.qBCProd, 4, 1);
			T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSQtde/vAliqProd = DecimalFormaterDelimiter(#.vAliqProd, 4, 1);
			T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSQtde/vCOFINS = DecimalFormaterDelimiter(#.vCOFINS, 2, 1);
		end
		else
		begin
			if(#.CST == '04' || #.CST == '06' || #.CST == '07' || #.CST == '08' || #.CST == '09')
			begin
				T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSNT = &new&;
				T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSNT/CST = #.CST;
			end
			else
			begin
				T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr = &new&;
				T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/CST = #.CST;

				if(IsNullOrEmpty(#.vBC) != ConvertToBoolean('True') && IsNullOrEmpty(#.pCOFINS) != ConvertToBoolean('True'))
				begin
					T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/Choice/vBC = DecimalFormaterDelimiter(#.vBC, 2, 1);
					T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/Choice/pCOFINS = DecimalFormaterDelimiter(#.pCOFINS, 4, 1);
					T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/vCOFINS = DecimalFormaterDelimiter(#.vCOFINS, 2, 1);
				end
				else
				begin
					if(IsNullOrEmpty(#.qBCProd) != ConvertToBoolean('True') && IsNullOrEmpty(#.vAliqProd) != ConvertToBoolean('True'))
					begin
						T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/Choice/qBCProd = DecimalFormaterDelimiter(#.qBCProd, 4, 1);
						T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/Choice/vAliqProd = DecimalFormaterDelimiter(#.vAliqProd, 4, 1);
						T.enviNFe/NFe/infNFe/det/imposto/COFINS/Choice/COFINSOutr/vCOFINS = DecimalFormaterDelimiter(#.vCOFINS, 2, 1);
					end
				end
			end

		end
	end
end
%endRuleContent;

