#.Owner = GetValueFromContext('OWNER');
#.PREFIXO = GetMicroFlowConfigParametersValue('PREFIXOJOBKEY', #.Owner);
#.SUFIXO = GetMicroFlowConfigParametersValue('SUFIXOJOBKEY', #.Owner);
#.SENTIDO = ToLower(GetMicroFlowConfigParametersValue('SUBINICIOFIM', #.Owner));
#.CODPFJLENGTH = GetMicroFlowConfigParametersValue('CODPFJLENGTH', #.Owner);
#.JOBKEY = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_ISSUER_REC/COD_PFJ;
#.PRIMEIROS_CARACTERES = 'primeiros caracteres';


if(IsNullOrEmpty(#.PREFIXO) != ConvertToBoolean('True'))
begin
	#.PREFIXO = StringFormat('{0}-', #.PREFIXO);
end

if(IsNullOrEmpty(#.SUFIXO) != ConvertToBoolean('True'))
begin
	#.SUFIXO = StringFormat('-{0}', #.SUFIXO);
end

if(#.SENTIDO == #.PRIMEIROS_CARACTERES)
begin
	#.JOBKEY = Substring(#.JOBKEY, 0, #.CODPFJLENGTH);
	#.JOBKEY = StringFormat('{0}{1}{2}_400', #.PREFIXO, #.JOBKEY, #.SUFIXO);
	T.enviNFe/NFe/infNFe/dadosAdic/Jobkey = #.JOBKEY;
end
else
begin
	#.JOBKEYLENGTH = GetLength(#.JOBKEY);
	#.POSICAO = Subtract(#.JOBKEYLENGTH, #.CODPFJLENGTH);
	#.JOBKEY = Substring(#.JOBKEY, #.POSICAO, #.CODPFJLENGTH);

	if(#.CODPFJLENGTH >= #.JOBKEYLENGTH)
	begin
		#.JOBKEY = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_ISSUER_REC/COD_PFJ;
		#.JOBKEY = StringFormat('{0}{1}{2}_400', #.PREFIXO, #.JOBKEY, #.SUFIXO);
		T.enviNFe/NFe/infNFe/dadosAdic/Jobkey = #.JOBKEY;

	end
	else
	begin
		#.JOBKEY = StringFormat('{0}{1}{2}_400', #.PREFIXO, #.JOBKEY, #.SUFIXO);
		T.enviNFe/NFe/infNFe/dadosAdic/Jobkey = #.JOBKEY;
	end
end
%endRuleContent;

