#.CST = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/CST_PIS;
if(IsNullOrEmpty(#.CST) == False())
begin	
	#.vBC = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_BASE_PIS;
	#.pPIS = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_ALIQ_PIS;
	#.vPIS = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/VLR_TOTAL_PIS;
	#.qBCProd = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/QUANT_BC_PIS;
	#.vAliqProd = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/ALIQ_PIS;	

	#.CST = PadRight(#.CST, '0', 2);
	if(#.CST == '01' || #.CST == '02')
	begin
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq = &new&;
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/CST = #.CST;
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/vBC = DecimalFormaterDelimiter(#.vBC, 2, 1);
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/pPIS = DecimalFormaterDelimiter(#.pPIS, 2, 1);
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
	end
	else
	begin
		if(#.CST == '03')
		begin
			T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde = &new&;
			T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/CST = #.CST;

			if(IsNullOrEmpty(#.qBCProd) != ConvertToBoolean('True'))
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/qBCProd = DecimalFormaterRetail(Replace(#.qBCProd, ',', '.'));
			end

			if(IsNullOrEmpty(#.vAliqProd) != ConvertToBoolean('True'))
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/vAliqProd = DecimalFormaterRetail(Replace(#.vAliqProd, ',', '.'));
			end

			if(IsNullOrEmpty(#.vPIS) != ConvertToBoolean('True'))
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
			end
		end

		else
		begin
			if(#.CST == '04' || #.CST == '06' || #.CST == '07' || #.CST == '08' || #.CST == '09')
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISNT = &new&;
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISNT/CST = #.CST;
			end

			else
			begin

				if(ConvertToInt32(#.CST) > 10)
				begin
					T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr = &new&;
					T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/CST = #.CST;

					if(IsNullOrEmpty(#.vBC) == True() || IsNullOrEmpty(#.pPIS) == True())
					begin
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/qBCProd = DecimalFormaterRetail(Replace(#.qBCProd, ',', '.'));
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/vAliqProd = DecimalFormaterRetail(Replace(#.vAliqProd, ',', '.'));
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
					end

					else
					begin
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/vBC = DecimalFormaterDelimiter(#.vBC, 2, 1);
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/pPIS = DecimalFormaterDelimiter(#.pPIS, 2, 1);
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
					end
				end
			end
		end
	end
end
%endRuleContent;

