%beginRuleContent;
//Variaveis Globais
#.DocumentKey = I.retEPECErp/chNFe;
#.DocumentKey = Replace(#.DocumentKey,'NFe','');
#.cStat = I.retEPECErp/cStat;
#.Status = 'E';
#.FSDA = '0';
#.EPEC = '0';
#.DocKey1 = Substring(#.DocumentKey, 0, '18');
#.DocKey2 = RemoveZerosLeft(Substring(#.DocumentKey,18,'18'));
#.DocKey3 = RemoveZerosLeft(Substring(#.DocumentKey,36,'8'));
#.FiscalDocId = I.retEPECErp/dadosAdic/FiscalDocId;
#.docDate = I.retEPECErp/dhRegEPEC;
#.docDate = Replace(#.docDate, 'T', ' ');

//quando data nao possui timezone (25 digitos) usa data corrente
if(GetLength(#.docDate) != 25)
begin
	#.docDate = DatetimeNowFormat('yyy-MM-dd HH:mm:ss');
end

//Captura valores do ConfigParameters
#.Owner = GetValueFromContext('OWNER');
#.retryvalue = GetMicroFlowConfigParametersValue('RETRYVALUE', #.Owner);
#.retryinterval = GetMicroFlowConfigParametersValue('RETRYINTERVAL', #.Owner);
#.ConnectionString = GetMicroFlowConfigParametersValue('CONNECTIONINPUT', #.Owner);
//Caso seja usado mais de uma contingencia, ou seja, EPEC --> FSDA
#.contingencyFSDA = GetMicroFlowConfigParametersValue('CONTINGENCYPARAMETER', #.Owner);

if(#.contingencyFSDA == 1 && #.cStat != '136')
begin
	if(ReturnPossibleFSDA(#.cStat) == True())
	begin
		#.FSDA = 1;
		#.EPEC = 4;
	end
end
else
begin
	if(#.cStat == '136')
	begin
		#.Status = 'A_C';
