	#.vAliqProd = I.OBJ_NFE_INFO/OBJ_FM_NFE_DOCHDR_REC/NFE_DETAIL_TBL/OBJ_FM_NFE_DOCDTL_REC/ALIQ_PIS;	

	#.CST = PadRight(#.CST, '0', 2);
	if(#.CST == '01' || #.CST == '02')
	begin
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq = &new&;
		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/CST = #.CST;
