		T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISAliq/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
	end
	else
	begin
		if(#.CST == '03')
		begin
			T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde = &new&;
			T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/CST = #.CST;

			if(IsNullOrEmpty(#.qBCProd) != ConvertToBoolean('True'))
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/qBCProd = DecimalFormaterRetail(Replace(#.qBCProd, ',', '.'));
			end

			if(IsNullOrEmpty(#.vAliqProd) != ConvertToBoolean('True'))
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/vAliqProd = DecimalFormaterRetail(Replace(#.vAliqProd, ',', '.'));
			end

