			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISQtde/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
			end
		end

		else
		begin
			if(#.CST == '04' || #.CST == '06' || #.CST == '07' || #.CST == '08' || #.CST == '09')
			begin
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISNT = &new&;
				T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISNT/CST = #.CST;
			end

			else
			begin

				if(ConvertToInt32(#.CST) > 10)
				begin
					T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr = &new&;
					T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/CST = #.CST;

