						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/qBCProd = DecimalFormaterRetail(Replace(#.qBCProd, ',', '.'));
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/vAliqProd = DecimalFormaterRetail(Replace(#.vAliqProd, ',', '.'));
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
					end

					else
					begin
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/vBC = DecimalFormaterDelimiter(#.vBC, 2, 1);
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/Choice/pPIS = DecimalFormaterDelimiter(#.pPIS, 2, 1);
						T.enviNFe/NFe/infNFe/det/imposto/PIS/Choice/PISOutr/vPIS = DecimalFormaterDelimiter(#.vPIS, 2, 1);
					end
				end
			end
		end
	end
end
