	T.Root/AccessKey = #.campoChaveAcesso;
end
else
begin
	if(#.tamanhoChaveAcesso == '35' && #.tamanhoChaveAcesso == '44')
	begin
		T.Root/AccessKey = ConcatString(#.campoChaveAcesso,CalculateVerifierDigit(#.campoChaveAcesso));
	end
	else
	begin
		#.codigoDaUFDoEmitente = I.LINHA001/CodigoDaUFDoEmitente001;
		#.AAMM = I.LINHA001/DataDeEmissaoDoDocumentoFiscal001;

		if(IsNullOrEmpty(#.AAMM) != True() && #.AAMM != 'xml')
		begin
			#.ano = Substring(#.AAMM, 2, 2);
			#.mes = Substring(#.AAMM, 5, 2);
		end

		#.cnpjEmit = I.LINHA004/NumeroDoCNPJDoEmitenteEmit;
		#.modelo = '55';
		#.serie = I.LINHA000/SerieNF;
		#.nNF = I.LINHA001/NumeroDoDocumentoFiscal001;
		#.tpEmi = I.LINHA001/FormaDaEmissaoDaNFe01;

		if(IsNullOrEmpty(#.codigoDaUFDoEmitente) != True() && IsNullOrEmpty(#.AAMM) != True() && IsNullOrEmpty(#.ano) != True() && IsNullOrEmpty(#.mes) != True() && IsNullOrEmpty(#.cnpjEmit) != True() && IsNullOrEmpty(#.modelo) != True() && IsNullOrEmpty(#.serie) != True() && IsNullOrEmpty(#.nNF) != True() && IsNullOrEmpty(#.tpEmi) != True())
		begin
			if(#.codigoDaUFDoEmitente != 'xml' && #.AAMM != 'xml' && #.ano != 'xml' && #.mes != 'xml' && #.cnpjEmit != 'xml' && #.modelo != 'xml' && #.serie != 'xml' && #.nNF != 'xml' && #.tpEmi != 'xml')
			begin
				T.Root/AccessKey = CreateNFeAcessKey(#.codigoDaUFDoEmitente,ConcatString(#.ano, #.mes),#.cnpjEmit,#.modelo,#.serie,#.nNF,#.tpEmi);
			end
		end
		else
		begin
			#.chNFe = I.LINHA000/ChaveAcesso;
			#.tipoOperacao = I.LINHA000/TipoOperacaoNF;

			if(IsNullOrEmpty(#.tipoOperacao) != True() && #.tipoOperacao != 'xml')
			begin
				if(#.tipoOperacao = '2')
				begin
					#.cnpjEmissorNF = I.HEADER/CNPJEmissorNF;

					if(IsNullOrEmpty(#.cnpjEmissorNF) != True())
					begin
						#.serieNFParam = PadLeft(#.serie, 3, '0');
						#.sequencialInicial = PadLeft(I.LINHA000/SequencialNFInicial, 9, '0');
						#.parameter = ConcatString(ConcatString(#.cnpjEmissorNF,#.serieNFParam),#.sequencialInicial);
						#.query = 'SELECT TOP 1 CONVERT(VARCHAR(18),DOCUMENTKEY1) + REPLICATE('0', 18 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY2))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY2) + REPLICATE('0', 8 - LEN(CONVERT(VARCHAR(MAX),DOCUMENTKEY3))) + CONVERT(VARCHAR(MAX),DOCUMENTKEY3) AS CHAVE FROM TBCONINTEGRATIONRETURN WHERE CNPJCOMPANY = SUBSTRING(@DOCUMENTKEY,1,14) AND SERIE = SUBSTRING(@DOCUMENTKEY,15,3) AND DOCUMENTNUMBER=SUBSTRING(@DOCUMENTKEY,18,9) AND SendType=1 ORDER BY INSERTDATE DESC';

					end
				end
				else
				begin
					if(IsNullOrEmpty(#.chNFe) != True())
					begin
						$.chaveMontada = #.chNFe;
						T.Root/AccessKey = ConcatString('NFe', #.chNFe);
					end
				end
			end
		end	
	end
end
