	end
	else
	begin
		#.codigoDaUFDoEmitente = I.LINHA001/CodigoDaUFDoEmitente001;
		#.AAMM = I.LINHA001/DataDeEmissaoDoDocumentoFiscal001;

		if(IsNullOrEmpty(#.AAMM) != True() && #.AAMM != 'xml')
