		if(IsNullOrEmpty(#.codigoDaUFDoEmitente) != True() && IsNullOrEmpty(#.AAMM) != True() && IsNullOrEmpty(#.ano) != True() && IsNullOrEmpty(#.mes) != True() && IsNullOrEmpty(#.cnpjEmit) != True() && IsNullOrEmpty(#.modelo) != True() && IsNullOrEmpty(#.serie) != True() && IsNullOrEmpty(#.nNF) != True() && IsNullOrEmpty(#.tpEmi) != True())
		begin
			if(#.codigoDaUFDoEmitente != 'xml' && #.AAMM != 'xml' && #.ano != 'xml' && #.mes != 'xml' && #.cnpjEmit != 'xml' && #.modelo != 'xml' && #.serie != 'xml' && #.nNF != 'xml' && #.tpEmi != 'xml')
			begin
				T.Root/AccessKey = CreateNFeAcessKey(#.codigoDaUFDoEmitente,ConcatString(#.ano, #.mes),#.cnpjEmit,#.modelo,#.serie,#.nNF,#.tpEmi);
			end
		end
		else
		begin
			#.chNFe = I.LINHA000/ChaveAcesso;
