#.xPed = '';
#.ContainsCompra = 0;
#.ContainsCana = 0;

if(#.IndexSuffix > 0)
begin
	#.SuffixLength = GetLength(#.SUFFIX);
	#.InitialIndex = Sum(#.IndexSuffix, #.SuffixLength);

	#.xPed = Substring(#.XML, #.InitialIndex, #.LENGTH);
	//#.xPed =  StringFormat('<{0}>{1}</{0}></compra>',#.NAME,#.xPed);
	#.xPed = Concat('<',#.NAME,'>',#.xPed,'</',#.NAME,'></compra>');
	#.xPed = Trim(#.xPed);

	if(Contains(#.XML,'<compra>') == True())
	begin
		#.ContainsCompra = 1;
	end
	if(Contains(#.XML,'<cana>') == True())
	begin
		#.ContainsCana = 1;
	end

	if(#.ContainsCompra == 0)
	begin
		if(#.ContainsCana == 1)
		begin
			#.XML = Replace(#.XML, '<cana>', '<compra></compra><cana>');
		end
		else
		begin
			#.XML = Replace(#.XML, '</infNFe>', '<compra></compra></infNFe>');
		end
	end


	#.XML = Replace(#.XML, '</compra>', #.xPed);

end

T.Linha1/Campo1 = #.XML;
