#.NewDocumentKey = I.abort/chaveAlterada;

#.Owner = GetValueFromContext('OWNER');
#.retryvalue = GetMicroFlowConfigParametersValue('RETRYVALUE', #.Owner);
#.retryinterval = GetMicroFlowConfigParametersValue('RETRYINTERVAL', #.Owner);
#.ConnectionString = GetMicroFlowConfigParametersValue('CONNECTIONINPUT', #.Owner);

#.OldKey1 = Substring(#.OldDocumentKey, 0, '18');
#.OldKey2 = Substring(#.OldDocumentKey, 18, '18');
#.OldKey3 = Substring(#.OldDocumentKey, 36, '8');

//Selecionar o ultimo FiscalDocId  da tabela tbControlDocuments
#.CommandSelectIdIntegracao = 'SELECT MAX(id_integracao) FROM tbControlDocuments';
#.CommandWhere = StringFormat(' WHERE DocType EQUAL 1 AND Dockey1 EQUAL {0} AND DocKey2 EQUAL {1} AND DockEy3 EQUAL {2}', #.OldKey1, #.OldKey2, #.OldKey3);

#.CommandSelectLastIdIntegracao = StringFormat('{0}{1}', #.CommandSelectIdIntegracao, #.CommandWhere);
#.Id_Integracao = OracleHelper(#.ConnectionString, #.CommandSelectLastIdIntegracao);

#.CommandContigency = 'SELECT ISCONTINGENCY FROM tbControlDocuments';
#.CommandContigency = StringFormat('{0}{1}', #.CommandContigency, #.CommandWhere);
#.IsContingency = OracleHelper(#.ConnectionString, #.CommandContigency);

#.NewKey1 = Substring(#.NewDocumentKey, 0, '18');
#.NewKey2 = Substring(#.NewDocumentKey, 18, '18');
#.NewKey3 = Substring(#.NewDocumentKey, 36, '8');

#.EPEC = Substring(#.NewKey2, 16, 1);
#.FSDA = 0;

if(#.EPEC == 4)
begin
	#.FSDA = 1;	
end

T.ActionParams/Param/Name = 'DocStatus';
T.ActionParams/Param/Value = 'A_C';

T.ActionParams/Param = &new&;	
T.ActionParams/Param/Name = 'DocumentKey';
T.ActionParams/Param/Value = #.NewDocumentKey;

T.ActionParams/Param = &new&;
T.ActionParams/Param/Name = 'Protocol';
T.ActionParams/Param/Value = '000000000000000';

T.ActionParams/Param = &new&;
T.ActionParams/Param/Name = 'Id_Integracao';
T.ActionParams/Param/Value = #.Id_Integracao;

T.ActionParams/Param = &new&;
T.ActionParams/Param/Name = 'EPEC';
T.ActionParams/Param/Value = #.EPEC;

T.ActionParams/Param = &new&;
T.ActionParams/Param/Name = 'FSDA';
T.ActionParams/Param/Value = #.FSDA;

T.ActionParams/Param = &new&; 
T.ActionParams/Param/Name = 'retryValue';
T.ActionParams/Param/Value = #.retryvalue;

T.ActionParams/Param = &new&;
T.ActionParams/Param/Name = 'retryInterval';
T.ActionParams/Param/Value = #.retryinterval;

//Atualiza a chave de acesso na tabela de controle e define como em contingência
#.CommandExecutionUpdateNewKey = StringFormat('UPDATE tbControlDocuments SET DocKey1 EQUAL {0} COMMA DocKey2 EQUAL {1} COMMA DocKey3 EQUAL {2} COMMA IsContingency EQUAL 1 WHERE DocType EQUAL 1 AND Dockey1 EQUAL {3} AND DocKey2 EQUAL {4} AND DockEy3 EQUAL {5}', #.NewKey1, #.NewKey2, #.NewKey3, #.OldKey1, #.OldKey2, #.OldKey3);
#.FiscalId = OracleHelper(#.ConnectionString, #.CommandExecutionUpdateNewKey);
%endRuleContent;

%beginRuleContent;
