#.ProcessKind = 1;
#.dtEvento = I.infEvento/dhRegEvento;
#.dtEvento = Replace(#.dtEvento, 'T', ' ');

if(GetLength(#.dtEvento) != 25)
begin
	#.dtEvento = DatetimeNowFormat('yyy-MM-dd HH:mm:ss');
end


if(#.tpEvento == '210200' || #.tpEvento == '210210' || #.tpEvento == '210220' || #.tpEvento == '210240')
begin
	#.ProcessKind = 0;
end


if(IsNullOrEmpty(#.Id_Integracao) == True())
begin
	#.SelectIDControl = 'SELECT MIN(ID) FROM tbControlDocuments WHERE Dockey1 EQUAL {0} AND DocKey2 EQUAL {1} AND DocKey3 EQUAL {2} AND Processed EQUAL 0 AND ProcessKind EQUAL {3}';
	#.QueryGetIdControle = StringFormat(#.SelectIDControl, #.DocKey1, #.DocKey2, #.DocKey3, #.ProcessKind);
	#.IdControle = OracleHelper(#.ConnectionString, #.QueryGetIdControle);

	#.QueryGetIdIntegracao = StringFormat('SELECT ID_INTEGRACAO FROM tbControlDocuments WHERE ID EQUAL {0}', #.IdControle);
	#.Id_Integracao = OracleHelper(#.ConnectionString, #.QueryGetIdIntegracao);	

	#.AtualizaProcessed = StringFormat('UPDATE tbControlDocuments set Processed EQUAL 1 WHERE ID EQUAL {0}', #.IdControle);
	#.resultado = OracleHelper(#.ConnectionString, #.AtualizaProcessed);
end

if(#.CSTAT == '135' || #.CSTAT == '136')
begin
	if(#.tpEvento == '110110' || #.tpEvento == '210200' || #.tpEvento == '210210' || #.tpEvento == '210220' || #.tpEvento == '210240')
	begin
		#.DocStatus = 'A';
	end
	if(#.tpEvento == '110140')
	begin
		#.DocStatus = 'A_C';
	end
end

