begin
	if(#.CSTAT == '135' || #.CSTAT == '136' || #.CSTAT == '151' || #.CSTAT == '155')
	begin
		#.DocStatus = 'C_A';
	end
	else
	begin
		#.DocStatus = 'C_E';
	end
end

