begin
	#.JOBKEY = Substring(#.JOBKEY, 0, #.CODPFJLENGTH);
	#.JOBKEY = StringFormat('{0}{1}{2}_400', #.PREFIXO, #.JOBKEY, #.SUFIXO);
	T.envEvento/evento/dadosAdic/JobKey = #.JOBKEY;
end
else
begin
	#.JOBKEYLENGTH = GetLength(#.JOBKEY);
	#.POSICAO = Subtract(#.JOBKEYLENGTH, #.CODPFJLENGTH);
	#.JOBKEY = Substring(#.JOBKEY, #.POSICAO, #.CODPFJLENGTH);

