%beginRuleContent;
#.DOC = GetOriginalDocument();

#.isProcNFeAut = RegexIsMatch(#.DOC, '<nfeProc');
#.isProcEventoCanc = RegexIsMatch(#.DOC, '<tpEvento>110111');

if(#.isProcNFeAut == True())
begin
	#.modFrete = GetXPathValue(#.DOC, '/nfeProc/NFe/infNFe/transp/modFrete', 'true');
	#.modFreteSettings = GetConfigParametersValue('MODFRETE_PROCNFE', '');
	#.resultModFrete = Contains(#.modFreteSettings, #.modFrete);

	#.CNPJEmit = GetXPathValue(#.DOC, '/nfeProc/NFe/infNFe/emit/CNPJ', 'true');
	#.cnpjEmitSettings = GetConfigParametersValue('CNPJ_EMIT_MODFRETE', '');
	#.cnpjEmitSettingsEmpty = IsNullOrEmpty(#.cnpjEmitSettings);

	#.chProcNFe = GetXPathValue(#.DOC, '/nfeProc/protNFe/infProt/chNFe', 'true');

	#.resultCnpjEmit = Contains(#.cnpjEmitSettings, #.CNPJEmit);

	#.deveEnviar = 0;

	if(#.resultModFrete == True())
	begin
		if(#.cnpjEmitSettingsEmpty == True())
		begin
			#.deveEnviar = 1;
