if(#.isProcCTeAut == True())
begin
	#.valueCNPJToma4 = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/ide/toma4/CNPJ', 'true');
	#.valueCNPJToma4Empty = IsNullOrEmpty(#.valueCNPJToma4);
	#.chProcCTe = GetXPathValue(#.DOC, '/cteProc/protCTe/infProt/chCTe', 'true');

	//ELSE IF não está funcionando.
	if(#.valueCNPJToma4Empty == True())
	begin
		#.valueToma3 = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/ide/toma3/toma', 'true');

		if(#.valueToma3 == '0')
		begin
			#.CNPJCustomer = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/rem/CNPJ', 'true');
		end
		else
		begin
			if(#.valueToma3 == '1')
			begin
				#.CNPJCustomer = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/exped/CNPJ', 'true');
			end
			else
			begin
				if(#.valueToma3 == '2')
				begin
					#.CNPJCustomer = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/receb/CNPJ', 'true');
				end
				else
				begin
					if(#.valueToma3 == 3)
					begin
						#.CNPJCustomer = GetXPathValue(#.DOC, '/cteProc/CTe/infCte/dest/CNPJ', 'true');
					end
				end
			end
		end
	end
	else
	begin
		#.CNPJCustomer = 	#.valueCNPJToma4;
	end

	#.cnpjDestSettings = GetConfigParametersValue('CNPJ_Control', '');
	#.cnpjDestSettingsEmpty = IsNullOrEmpty(#.cnpjDestSettings);

	#.resultCnpjDest = Contains(#.cnpjDestSettings, #.CNPJCustomer);

	#.deveEnviar = 0;

	if(#.cnpjDestSettingsEmpty == True())
	begin
		#.deveEnviar = 1;
	end

	if(#.resultCnpjDest == True())
	begin
		#.deveEnviar = 1;
	end

	if(#.deveEnviar == 1)
	begin
		T.Linha/Campo = 'd4f4a95c-d4e7-46eb-87e1-d6aa42ddd5c5';
	end
	else
	begin
		T.Linha/Campo = Concat('O documento é inválido e não será enviado. Chave do documento: ', #.chProcCTe);
	end
end
else
begin
	if(#.isProcEventoCanc == True())
	begin
		T.Linha/Campo = 'c4b651f0-3b7a-4925-877d-73800e529d96';
	end
	else
	begin
		T.Linha/Campo = 'O documento é inválido e não será enviado.';
	end
end
%endRuleContent;

