#.enviNFeInitial = '<?xml version="1.0" encoding="utf-8"?><enviNFe versao="{0}" xmlns="http://www.portalfiscal.inf.br/nfe"><idLote>0000000000001</idLote><indSinc>0</indSinc>';
#.enviNFeInitial = StringFormat(#.enviNFeInitial, #.versionNFe);

//Montagem dadosAdic - Documento original
#.dadosAdicOriginalDocument = ConvertToBase64String(#.originalDocument, 'UNICODE');
#.dadosAdicOriginalDocument = StringFormat('<OriginalDocument>{0}</OriginalDocument>', #.dadosAdicOriginalDocument);

//Montagem do dadosAdic - JobKey
#.CNPJEmit = GetXPathValue(#.originalDocument, '/NFe/NFP01_LISTA/CNPJ_EMITENTE', 'false');
#.dadosAdicJobKey = StringFormat('<JobKey>{0}_{1}</JobKey>', #.CNPJEmit, #.versionNFe);

//Montagem do dadosAdic - Impressão
#.dadosAdicPrinter = GetXPathValue(#.originalDocument, '/NFe/NFP01_LISTA/IDENT_PRT_DANFE', 'false');

if(IsNullOrEmpty(#.dadosAdicPrinter) == False())
begin
	#.dadosAdicPrinter = StringFormat('<PrinterKey>{0}</PrinterKey>', #.dadosAdicPrinter);
end

//Captura o nome original do documento
#.patternName = GetTargetFileName();
#.paramSplit = '\\';
#.patternName = SplitValue(#.patternName, #.paramSplit, '0', '2', 'false');
#.patternName = Replace(#.patternName, '.xml', '');
#.patternName = StringFormat('<PatternName>{0}</PatternName>', #.patternName);

//Montagem do dadosAdic
#.dadosAdic = StringFormat('<dadosAdic>{0}{1}{2}{3}</dadosAdic></infNFe></NFe></enviNFe>', #.dadosAdicJobKey, #.patternName, #.dadosAdicPrinter, #.dadosAdicOriginalDocument);

#.extractDocument = Replace(#.extractDocument, '</infNFe></NFe>', #.dadosAdic);
T.Linha/Campo = StringFormat('{0}{1}', #.enviNFeInitial, #.extractDocument);
%endRuleContent;

