#.procNFeInitial = '<nfeProc versao="{0}" xmlns="http://www.portalfiscal.inf.br/nfe">';
#.procNFeInitial = StringFormat(#.procNFeInitial, #.versionNFe);

//Remove a tag XML do arquivo de envio CONFIG e salva as informações do cabeçalho
#.documentValueConfig = RemoveXpathNode(#.originalDocumentDadosAdic, 'XML', 'true');
#.documentValueConfig = Replace(#.documentValueConfig, '<NFe>', '<OriginalValueConfig>');
#.documentValueConfig = Replace(#.documentValueConfig, '</NFe>', '</OriginalValueConfig>');

//Remove a tag OriginalDocument do dadosAdic e prepara o infProt para o layout procNFe
#.documentInfProt = RemoveXpathNode(#.documentInfProt, 'OriginalDocument', 'true');
