#.documentInfProt = StringFormat(#.infProtInitial, #.versionNFe, #.documentInfProt, '</protNFe>', #.documentValueConfig, '</nfeProc>');

//Montagem do nfeProc
#.extractDocument = Replace(#.extractDocument, '</NFe>', #.documentInfProt);
