#.documentoDeEnvio = ConvertFromBase64String(#.documentoDeEnvio, 'UNICODE');

//Pega a integração do e-Forms sem o documento original de envio do ERP em base64
#.documentoDeRetorno = RemoveXpathNode(#.originalDocument, 'OriginalDocument', 'true');

//Montagem do cabeçalho procNFe e versão
