%beginRuleContent;
// ConnectionString do banco SQLite
#.connectionString = GetCurrentExecutation();
#.connectionString = Replace(#.connectionString, 'AppConnector.DIR\\Bin', 'Database');
#.connectionString = ConcatString(#.connectionString, '\\NDD_NFECONTROL.db');

//Montagem do documentNumberCut
#.numeroNFe = PadLeft(I.NFe/NFP01_LISTA/CFG_NUMERO_NF, '0', 9);
#.serieNFe = PadLeft(I.NFe/NFP01_LISTA/CFG_SERIE_NF, '0', 3);
#.CNPJ = PadLeft(I.NFe/NFP01_LISTA/CNPJ_EMITENTE, '0', 9);
#.MOD = I.NFe/NFP01_LISTA/MOD;
#.documentNumberCut = StringFormat('{0}{1}{2}{3}', #.CNPJ, #.MOD, #.serieNFe, #.numeroNFe);

//Montagem do Select para verificar se existe autorização processada referente ao documento enviado de cancelamento
#.selectExistKey = 'SELECT COUNT(*) FROM TBCONTROLDOCUMENTS WHERE DocNumberCut EQUAL QUOTE{0}QUOTE';
#.selectExistKey = StringFormat(#.selectExistKey, #.documentNumberCut);

//Executando o comando para verificar se existe o registro
#.executionCommand = SQLiteHelper(#.connectionString, #.selectExistKey);
#.log = LogHelperMapper('executionCommand', #.executionCommand);

//Montagem do Select para capturar a chave existente da autorização para o cancelamento
#.selectKey = 'SELECT (DOCKEY1 || DOCKEY2 || DOCKEY3) FROM TBCONTROLDOCUMENTS WHERE DOCNUMBERCUT EQUAL QUOTE{0}QUOTE';
#.selectKey = StringFormat(#.selectKey, #.documentNumberCut);
#.log = LogHelperMapper('selectKey', #.selectKey);

//Captura a chave do documento
if(#.executionCommand != 0)
begin
	#.executionCommand = SQLiteHelper(#.connectionString, #.selectKey);
	#.log = LogHelperMapper('executionCommand no IF', #.executionCommand);
	#.contains = Contains(#.executionCommand, 'Exception');
	if(#.contains == True())
	begin
		T.nfeCancInut/chNFe = '';
	end
	else
	begin
		T.nfeCancInut/chNFe = #.executionCommand;
	end
end
%endRuleContent;

