begin
	#.InitialIndex = Subtract(#.NumSize, 9);
	#.nNF = Substring(I.Rps/InfRps/IdentificacaoRps/Numero, #.InitialIndex, 9);
	$.nNF = PadLeft(#.nNF, 0, 9);
end
else
begin
	$.nNF = PadLeft(I.Rps/InfRps/IdentificacaoRps/Numero, 0, 9);
end

