#.NFeKey = Concat(#.UF,#.Ano,#.Mes,#.CNPJ,#.Mod,#.Serie,$.nNF,#.tpEmis,$.cNF);
$.Digit = CalculateVerifierDigit(#.NFeKey);
#.DocumentKey = Concat(#.NFeKey, $.Digit);

T.enviNFe/NFe/infNFe/Id = Concat('NFe',#.DocumentKey);
%endRuleContent;

